function validate([properties, k]) {
  if (properties.length < 1 || properties.length > 100) return 'properties needs 1 to 100 rows.';
  const m = properties[0].length;
  if (m < 1 || m > 100) return 'Each row needs 1 to 100 values.';
  if (properties.some((row) => row.length !== m)) return 'Every row must have the same length m.';
  if (properties.some((row) => row.some((v) => v < 1 || v > 100))) return 'Each value is between 1 and 100.';
  if (k < 1 || k > m) return 'k is between 1 and m, the length of a row.';
  return null;
}

