  const n = properties.length;
  const distinct = properties.map((row) => new Set(row));
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (node) => {
    while (parent[node] !== node) {
      parent[node] = parent[parent[node]];
      node = parent[node];
    }
    return node;
  };
  let components = n;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const rootI = find(i);
      const rootJ = find(j);
      if (rootI === rootJ) {
        continue;
      }
      let shared = 0;
      for (const value of distinct[i]) {
        if (distinct[j].has(value)) {
          shared++;
        }
      }
      if (shared >= k) {
        parent[rootI] = rootJ;
        components--;
      }
    }
  }
  return components;
}

