function numberOfComponents(properties, k) {
  // Mark each row's values in a 1..100 table, build every edge, then count components with a depth-first search.
  const n = properties.length;
  const present = properties.map((row) => {
    const mark = new Array(101).fill(false);
    for (const value of row) mark[value] = true;
    return mark;
  });
  const joined = (a, b) => {
    let common = 0;
    for (let value = 1; value <= 100; value++) if (present[a][value] && present[b][value]) common++;
    return common >= k;
  };
  const seen = new Array(n).fill(false);
  let count = 0;
  for (let start = 0; start < n; start++) {
    if (seen[start]) continue;
    count++;
    seen[start] = true;
    const stack = [start];
    while (stack.length) {
      const node = stack.pop();
      for (let other = 0; other < n; other++) {
        if (!seen[other] && joined(node, other)) {
          seen[other] = true;
          stack.push(other);
        }
      }
    }
  }
  return count;
}

