function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size !== 'large') {
    const n = pick(1, 6);
    const m = pick(1, 4);
    const top = pick(1, 6);
    const properties = Array.from({ length: n }, () => Array.from({ length: m }, () => pick(1, top)));
    return [properties, pick(1, m)];
  }
  // Rows come in groups, and each group draws from its own window of 1..100, so rows of different groups share nothing.
  const n = 100;
  const m = pick(5, 100);
  const groups = pick(1, 25);
  const width = Math.floor(100 / groups);
  const properties = Array.from({ length: n }, () => {
    const first = 1 + pick(0, groups - 1) * width;
    return Array.from({ length: m }, () => first + pick(0, width - 1));
  });
  // Aim k near what two rows of one group typically share, so some of those pairs are joined and some are not.
  const perRow = width * (1 - Math.pow(1 - 1 / width, m));
  const typical = (perRow * perRow) / width;
  const k = Math.max(1, Math.min(m, Math.round(typical * (0.7 + 0.6 * rand()))));
  return [properties, k];
}
